/* From Uiverse.io by AnthonyPreite  - Tags: minimalist, switch, theme-switch */
.__UIV_SCOPE__ .switch {
  position: relative;
  display: inline-block;
  width: 60px;
  height: 34px;
}

.__UIV_SCOPE__ .switch .checkbox {
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: transparent;
  -webkit-transition: 0.4s;
  transition: 0.4s;
  box-shadow: 1px 1px 5px 0 #d84f68 inset;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  height: 26px;
  width: 26px;
  left: 4px;
  bottom: 4px;
  background-color: #d84f68;
  -webkit-transition: 0.4s;
  transition: 0.4s;
  box-shadow: inset 1px 1px 2px 0px #ff7ca7;
}

.__UIV_SCOPE__ .checkbox:checked + .slider {
  box-shadow: 1px 1px 5px 0 #2a9d8f inset;
}

.__UIV_SCOPE__ .checkbox:checked + .slider:before {
  -webkit-transform: translateX(26px);
  -ms-transform: translateX(26px);
  transform: translateX(26px);
  background-color: #2a9d8f;
  box-shadow: inset -1px 1px 2px 0px #a3fff4;
}

/* Rounded sliders */
.__UIV_SCOPE__ .slider.round {
  border-radius: 34px;
}

.__UIV_SCOPE__ .slider.round:before {
  border-radius: 50%;
}
